using System;using System.Collections;using System.Reflection;using UnityEngine;
public sealed class BalanceServeTests:MonoBehaviour
{
 public static bool OverrideAxes;public static float FanAxis,ZhaoAxis;static bool started;
 const BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Static;int failures,checks;
 Component fan,zhao;Rigidbody2D fb,zb,ball;Type pt;float leftLine,rightLine;
 public static void Boot(){if(started)return;started=true;var o=new GameObject("BalanceServeTests");DontDestroyOnLoad(o);o.AddComponent<BalanceServeTests>();}
 void Check(bool ok,string label){checks++;Debug.Log((ok?"BALANCE PASS ":"BALANCE FAIL ")+label);if(!ok)failures++;}
 void Near(float x,float y,string label){Check(Mathf.Abs(x-y)<.025f,label+" actual="+x+" expected="+y);}
 object State(Component p){return typeof(GameAIMod).GetMethod("GetState",Private).Invoke(null,new object[]{p});}
 void Put(object o,string n,object v){o.GetType().GetField(n).SetValue(o,v);}
 object Read(object o,string n){return o.GetType().GetField(n).GetValue(o);}
 void Decide(Component p,object s){Put(s,"frame",-1);typeof(GameAIMod).GetMethod("UpdateDecision",Private).Invoke(null,new[]{(object)p,s});}
 void Move(Component p,Rigidbody2D b,float x){p.transform.position+=Vector3.right*(x-b.position.x);Physics2D.SyncTransforms();}
 float Joints(Component p){float max=0;foreach(HingeJoint2D j in p.GetComponentsInChildren<HingeJoint2D>())if(j.connectedBody!=null)max=Mathf.Max(max,Vector2.Distance(j.transform.TransformPoint(j.anchor),j.connectedBody.transform.TransformPoint(j.connectedAnchor)));return max;}
 IEnumerator Scene(int mode,bool skills){OverrideAxes=true;FanAxis=ZhaoAxis=0;PlayerSkills.Enabled=skills;typeof(GameAIMod).GetMethod("StartGame",Private).Invoke(null,new object[]{mode});yield return new WaitForSeconds(.12f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);fb=(Rigidbody2D)pt.GetField("rb").GetValue(fan);zb=(Rigidbody2D)pt.GetField("rb").GetValue(zhao);Component bc=FindObjectOfType(Type.GetType("Ball, Assembly-CSharp")) as Component;ball=bc.GetComponent<Rigidbody2D>();Type gt=Type.GetType("GoalTrigger, Assembly-CSharp");foreach(UnityEngine.Object o in FindObjectsOfType(gt)){Component g=(Component)o;Collider2D c=g.GetComponent<Collider2D>();if(g.transform.position.x<0)leftLine=c.bounds.max.x;else rightLine=c.bounds.min.x;}
  Near(((Vector3)pt.GetProperty("OriginPos").GetValue(fan,null)).x,leftLine,"Fan reset origin on goal line mode="+mode+" skills="+skills);Near(((Vector3)pt.GetProperty("OriginPos").GetValue(zhao,null)).x,rightLine,"Zhao reset origin on goal line mode="+mode+" skills="+skills);
  Vector3 origin=(Vector3)bc.GetType().GetProperty("OriginPos").GetValue(bc,null);Near(origin.x,0,"center ball spawn unchanged");Near(origin.y,3.27f,"ball drop height unchanged");Near(((Vector3)bc.GetType().GetField("leftPos").GetValue(bc)).x,-3.6f,"left ball spawn unchanged");Near(((Vector3)bc.GetType().GetField("rightPos").GetValue(bc)).x,3.6f,"right ball spawn unchanged");
  Check(Joints(fan)<.3f&&Joints(zhao)<.3f,"initial goal-line placement preserves connected skeletons");
 }
 IEnumerator Opening(int mode,bool skills){yield return Scene(mode,skills);OverrideAxes=false;Component p=mode==1?zhao:fan;Rigidbody2D b=mode==1?zb:fb;float direction=mode==1?-1f:1f;float start=b.position.x;bool retreat=false,badJump=false;float error=0;object s=State(p);for(int i=0;i<110;i++){yield return new WaitForFixedUpdate();float axis=GameAIMod.GetAxis("Horizontal",p);bool approach=(bool)Read(s,"serveApproach");if(approach&&axis*direction<-.01f)retreat=true;if((bool)Read(s,"jump")&&Mathf.Abs(ball.position.x-b.position.x)>1.5f)badJump=true;error=Mathf.Max(error,Joints(p));}
  Check(!retreat,"AI never retreats during untouched opening side="+p.name+" skills="+skills);Check(!badJump,"AI avoids distant opening jumps side="+p.name+" skills="+skills);Check((b.position.x-start)*direction>2f,"AI actively advances from goal line side="+p.name+" displacement="+(b.position.x-start)*direction);Check(error<.3f,"AI native movement keeps limbs connected error="+error);
  OverrideAxes=true;FanAxis=ZhaoAxis=0;Component stick=p.GetComponent(Type.GetType("StickManController, Assembly-CSharp"));stick.GetType().GetMethod("Reset").Invoke(stick,null);Physics2D.SyncTransforms();Near(b.position.x,p.name=="Fan"?leftLine:rightLine,"native reset returns player to goal line");
 }
 void DecisionCases(Component p,Rigidbody2D b,float direction){object s=State(p);Move(p,b,-direction*1.2f);b.velocity=Vector2.right*direction*4f;ball.position=new Vector2(0,3.27f);ball.velocity=Vector2.zero;Put(s,"serveApproach",true);Put(s,"lastServeReset",Time.time);Put(s,"lastJump",-10f);pt.GetField("isOnGround").SetValue(p,true);Decide(p,s);Check((float)Read(s,"axis")*direction>=0f,"opening brake never uses backward input "+p.name);Check(!(bool)Read(s,"jump"),"opening brake avoids premature jump "+p.name);
  Move(p,b,-direction*2.2f);b.velocity=Vector2.zero;Transform head=p.transform.Find("Head");ball.position=new Vector2(0,head.position.y+.9f);ball.velocity=Vector2.down;Put(s,"lastJump",-10f);Decide(p,s);Check(!(bool)Read(s,"jump"),"distant aerial ball does not cause jump "+p.name);
  Move(p,b,-direction*.55f);b.velocity=Vector2.zero;ball.position=new Vector2(0,head.position.y+.9f);ball.velocity=Vector2.down;Put(s,"lastJump",-10f);Decide(p,s);Check((bool)Read(s,"jump"),"aligned reachable descending ball allows attacking jump "+p.name);
  ball.position=new Vector2(b.position.x-direction*3f,-1.3f);ball.velocity=new Vector2(-direction*2f,0);Put(s,"serveApproach",false);b.velocity=Vector2.zero;Decide(p,s);Check((float)Read(s,"axis")*direction<0f,"normal play still recovers rear ball "+p.name);
 }
 IEnumerator Retreat(bool skills){yield return Scene(0,skills);Move(fan,fb,3.5f);Move(zhao,zb,-3.5f);ball.position=new Vector2(0,40);ball.velocity=Vector2.zero;FanAxis=-1;ZhaoAxis=1;Near(PlayerMovement.GetMovementLimit(4,fan),3.9f,"Fan native retreat cap all modes");Near(PlayerMovement.GetMovementLimit(4,zhao),6f,"Zhao native retreat cap matches prior Fan all modes");float e=0;for(int i=0;i<90;i++){yield return new WaitForFixedUpdate();e=Mathf.Max(e,Mathf.Max(Joints(fan),Joints(zhao)));}Check(e<.3f,"both retreat gaits keep native joints connected skills="+skills+" error="+e);Check(fb.velocity.x<-.1f&&zb.velocity.x>.1f,"both physically retreat under native controller skills="+skills);}
 IEnumerator Start(){Application.targetFrameRate=60;QualitySettings.vSyncCount=0;Application.runInBackground=true;AudioListener.volume=0;yield return new WaitForSeconds(.2f);
  foreach(bool enabled in new[]{false,true}){yield return Scene(0,enabled);FanAxis=-1;ZhaoAxis=1;Near(PlayerMovement.GetMultiplier(fan),.975f,"Fan retreat is 65 percent of old 1.5x");Near(PlayerMovement.GetMultiplier(zhao),1.5f,"Zhao retreat matches old Fan 1.5x");FanAxis=1;Near(PlayerMovement.GetMultiplier(fan),enabled?1.1f:1f,"attack sprint is 10 percent only in stunt mode");Near(PlayerMovement.GetMovementForce(1000,fan),enabled?1100:1000,"native sprint force matches cap multiplier");if(enabled){PlayerSkills.NotifyMovement(zhao,1f);var zs=zhao.GetComponent<PlayerSkills>();float[] effects=(float[])typeof(PlayerSkills).GetField("effects",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(zs);Check(effects[6]>=0,"emergency retreat animation still triggers automatically");}FanAxis=ZhaoAxis=0;}
  foreach(bool enabled in new[]{false,true})foreach(int mode in new[]{1,2})yield return Opening(mode,enabled);
  yield return Scene(0,false);Move(zhao,zb,7);DecisionCases(fan,fb,1);Move(fan,fb,-7);DecisionCases(zhao,zb,-1);
  yield return Retreat(false);yield return Retreat(true);
  Debug.Log("BALANCE SERVE COMPLETE checks="+checks+" failures="+failures);Application.Quit();
 }
}
